-- create temporary table of additions/deletions
CREATE OR REPLACE TEMPORARY TABLE UTIL.tmp_ADF_MYSQLDB_COPY_CONTROL
(
    ADF_MYSQLDB_COPY_CONTROL_KEY VARCHAR NULL,
    INSERT_DATETIME TIMESTAMP_TZ(9) NOT NULL,
    UPDATE_DATETIME TIMESTAMP_TZ(9) NOT NULL,
    IS_ACTIVE BOOLEAN NOT NULL,
    IS_INCREMENTAL_FLAG BOOLEAN NOT NULL,
    IS_TRUNCATE_TABLE_FLAG BOOLEAN NOT NULL,
    IS_PARTITION_BY_DATE_FLAG BOOLEAN NOT NULL,
    SOURCE_DATABASE_NAME VARCHAR NOT NULL,
    SOURCE_TABLE_NAME VARCHAR NOT NULL,
    SOURCE_QUERY VARCHAR NOT NULL,
    SOURCE_LOOKUP_COLUMN_NAME VARCHAR,
    SOURCE_SECRET_VALUE VARCHAR NOT NULL,
    TARGET_DATABASE_NAME VARCHAR NOT NULL,
    TARGET_SCHEMA_NAME VARCHAR NOT NULL,
    TARGET_TABLE_NAME VARCHAR NOT NULL,
    TARGET_DATA_LAKE_PATH VARCHAR NOT NULL,
    ADF_TRIGGER_NAME VARCHAR,
    IS_PARTITION_BY_STRING BOOLEAN NOT NULL,
    PARTITION_BY_STRING_COLUMN_NAME VARCHAR,
    TARGET_CONTAINER_NAME VARCHAR,
    CONSTRAINT UK_ADF_COPY_CONTROL UNIQUE (TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME)
)
;

-- items to place into temporary table
;
-- Update the File Copy Control Key for all records
UPDATE UTIL.tmp_ADF_MYSQLDB_COPY_CONTROL
SET ADF_MYSQLDB_COPY_CONTROL_KEY = UTIL.FXN_ARRAY_HASH([SOURCE_DATABASE_NAME, SOURCE_TABLE_NAME])
;

-- Check for invalid/duplicated records in temp table before merging
EXECUTE IMMEDIATE $$
DECLARE
  dup_primary_key_exception EXCEPTION (-20001, 'DUPLICATE Primary Keys Detected.');
  dup_unique_key_exception EXCEPTION (-20002, 'DUPLICATE Unique Keys Detected.');
  dup_count INTEGER;
BEGIN
    SELECT COUNT(1) INTO :dup_count 
        FROM(SELECT ADF_MYSQLDB_COPY_CONTROL_KEY, COUNT(1) FROM UTIL.TMP_ADF_MYSQLDB_COPY_CONTROL GROUP BY ADF_MYSQLDB_COPY_CONTROL_KEY HAVING COUNT(1) > 1);
    IF (dup_count > 0) THEN
    RAISE dup_primary_key_exception;
	END IF;

    SELECT COUNT(1) INTO :dup_count 
        FROM(SELECT TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, COUNT(1) FROM UTIL.TMP_ADF_MYSQLDB_COPY_CONTROL GROUP BY TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME HAVING COUNT(1) > 1);
    IF (dup_count > 0) THEN
    RAISE dup_unique_key_exception;
	END IF;
END;
$$;

--Use a minus query to find any diffs and update or insert as needed
MERGE INTO UTIL.ADF_MYSQLDB_COPY_CONTROL AS TGT

USING (SELECT ADF_MYSQLDB_COPY_CONTROL_KEY, INSERT_DATETIME, UPDATE_DATETIME, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME
    FROM UTIL.tmp_adf_mysqldb_copy_control
    MINUS
       SELECT ADF_MYSQLDB_COPY_CONTROL_KEY, INSERT_DATETIME, UPDATE_DATETIME, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME
    FROM UTIL.ADF_MYSQLDB_COPY_CONTROL)
    AS SRC
    
ON (
    TGT.TARGET_DATABASE_NAME = SRC.TARGET_DATABASE_NAME
    AND TGT.TARGET_TABLE_NAME = SRC.TARGET_TABLE_NAME
    )
    
WHEN MATCHED
THEN UPDATE
    SET TGT.ADF_MYSQLDB_COPY_CONTROL_KEY = SRC.ADF_MYSQLDB_COPY_CONTROL_KEY,
    TGT.INSERT_DATETIME = SRC.INSERT_DATETIME,
    TGT.UPDATE_DATETIME = SRC.UPDATE_DATETIME,
    TGT.IS_ACTIVE = SRC.IS_ACTIVE,
    TGT.IS_INCREMENTAL_FLAG = SRC.IS_INCREMENTAL_FLAG,
    TGT.IS_TRUNCATE_TABLE_FLAG = SRC.IS_TRUNCATE_TABLE_FLAG,
    TGT.IS_PARTITION_BY_DATE_FLAG = SRC.IS_PARTITION_BY_DATE_FLAG,
    TGT.SOURCE_DATABASE_NAME = SRC.SOURCE_DATABASE_NAME,
    TGT.SOURCE_TABLE_NAME = SRC.SOURCE_TABLE_NAME,
    TGT.SOURCE_QUERY = SRC.SOURCE_QUERY,
    TGT.SOURCE_LOOKUP_COLUMN_NAME = SRC.SOURCE_LOOKUP_COLUMN_NAME,
    TGT.SOURCE_SECRET_VALUE = SRC.SOURCE_SECRET_VALUE,
    TGT.TARGET_DATABASE_NAME = SRC.TARGET_DATABASE_NAME,
    TGT.TARGET_SCHEMA_NAME = SRC.TARGET_SCHEMA_NAME,
    TGT.TARGET_TABLE_NAME = SRC.TARGET_TABLE_NAME,
    TGT.TARGET_DATA_LAKE_PATH = SRC.TARGET_DATA_LAKE_PATH,
    TGT.ADF_TRIGGER_NAME = SRC.ADF_TRIGGER_NAME,
    TGT.IS_PARTITION_BY_STRING = SRC.IS_PARTITION_BY_STRING,
    TGT.PARTITION_BY_STRING_COLUMN_NAME = SRC.PARTITION_BY_STRING_COLUMN_NAME,
    TGT.TARGET_CONTAINER_NAME = SRC.TARGET_CONTAINER_NAME
WHEN NOT MATCHED
THEN INSERT
    (ADF_MYSQLDB_COPY_CONTROL_KEY, INSERT_DATETIME, UPDATE_DATETIME, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME,  SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME)
VALUES
    (SRC.ADF_MYSQLDB_COPY_CONTROL_KEY, SRC.INSERT_DATETIME, SRC.UPDATE_DATETIME, SRC.IS_ACTIVE, SRC.IS_INCREMENTAL_FLAG,src.IS_TRUNCATE_TABLE_FLAG, src.IS_PARTITION_BY_DATE_FLAG, src.SOURCE_DATABASE_NAME, src.SOURCE_TABLE_NAME, src.SOURCE_QUERY, src.SOURCE_LOOKUP_COLUMN_NAME, src.SOURCE_SECRET_VALUE, src.TARGET_DATABASE_NAME, src.TARGET_SCHEMA_NAME, src.TARGET_TABLE_NAME, src.TARGET_DATA_LAKE_PATH, src.ADF_TRIGGER_NAME, src.IS_PARTITION_BY_STRING, src.PARTITION_BY_STRING_COLUMN_NAME, src.TARGET_CONTAINER_NAME);

-- delete from target
DELETE FROM UTIL.ADF_MYSQLDB_COPY_CONTROL AS TGT
USING
(SELECT INSERT_DATETIME, UPDATE_DATETIME, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME
    FROM UTIL.ADF_MYSQLDB_COPY_CONTROL
    MINUS
    SELECT INSERT_DATETIME, UPDATE_DATETIME, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME
    FROM UTIL.tmp_adf_mysqldb_copy_control) AS SRC
WHERE 
    TGT.TARGET_DATABASE_NAME = SRC.TARGET_DATABASE_NAME
    AND TGT.TARGET_SCHEMA_NAME = SRC.TARGET_SCHEMA_NAME
    AND TGT.TARGET_TABLE_NAME = SRC.TARGET_TABLE_NAME
    ;